.form-field {
  margin-bottom: 2rem;
}

fieldset {
  border: none;
  padding: 0;
  min-width: 0;
}

legend {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--color-text);
  margin-bottom: 0.25rem;
  line-height: 1.5;
}

.required-marker {
  color: var(--color-error);
  margin-left: 0.125rem;
}

.required-note {
  font-size: 0.8125rem;
  color: var(--color-text-muted);
  margin-bottom: 1.25rem;
}

