  position: absolute;
  opacity: 0;
  width: 1.25rem;
  height: 1.25rem;
  margin: 0;
  cursor: pointer;
}

/* Custom radio circle */
.radio-custom {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 1.25rem;
  height: 1.25rem;
  border: 2px solid var(--color-border-hover);
  border-radius: 50%;
  background: #fff;
  transition: border-color 0.15s, background 0.15s;
