  position: absolute;
  top: -100%;
  left: 1rem;
  background: var(--color-primary);
  color: #fff;
  padding: 0.5rem 1rem;
  border-radius: var(--radius-btn);
  font-weight: 600;
  text-decoration: none;
  z-index: 100;
  transition: top 0.1s;
}
.skip-link:focus {
  top: 1rem;
}

