  border-radius: var(--radius-card);
  box-shadow: var(--shadow-card);
  padding: 2.5rem;
}

h1 {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 0.5rem;
}

.intro {
  color: var(--color-text-muted);
  font-size: 0.9375rem;
  line-height: 1.6;
  margin-bottom: 2rem;
}

/* ── Form & fieldset ─────────────────────────────────────────── */
.form-field {
  margin-bottom: 2rem;
}

fieldset {
  border: none;
  padding: 0;
  min-width: 0;
}

legend {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--color-text);
  margin-bottom: 0.25rem;
  line-height: 1.5;
}

.required-marker {
  color: var(--color-error);
  margin-left: 0.125rem;
}

.required-note {
  font-size: 0.8125rem;
  color: var(--color-text-muted);
  margin-bottom: 1.25rem;
}

/* ── Radio options ───────────────────────────────────────────── */
.radio-options {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.radio-label {
  display: flex;
  align-items: center;
  gap: 0.875rem;
  padding: 0.875rem 1rem;
  border: 1.5px solid var(--color-border);
  border-radius: 0.625rem;
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s, box-shadow 0.15s;
  position: relative;
}

.radio-label:hover {
  border-color: var(--color-primary);
  background: #f5f3ff;
}

