}

.btn-submit:focus-visible {
  outline: 3px solid var(--color-primary-focus-ring);
  outline-offset: 2px;
}

/* ── Status message ──────────────────────────────────────────── */
.status-message {
  margin-top: 1.25rem;
  font-size: 0.9375rem;
  font-weight: 500;
  min-height: 1.5rem;
}

.status-message.success {
  padding: 0.75rem 1rem;
