  const errorEl = document.getElementById('notification-error');
  const statusEl = document.getElementById('status-message');

  form.addEventListener('submit', function (e) {
    e.preventDefault();

    const selected = form.querySelector('input[name="notification"]:checked');

    if (!selected) {
      // Show error and mark fieldset invalid
      errorEl.hidden = false;
      fieldset.classList.add('is-invalid');

      // Move focus to the first radio so the user knows where to act
      form.querySelector('input[name="notification"]').focus();
      return;
    }

    // Clear any previous error
    errorEl.hidden = true;
    fieldset.classList.remove('is-invalid');

    // Map value to a readable label
    const labels = {
      email: 'Email',
      sms: 'SMS',
      push: 'Push Notifications',
    };
    const label = labels[selected.value] || selected.value;

    // Announce success via the live region
    statusEl.textContent = '';
    statusEl.classList.remove('success');

    // Small timeout lets screen readers re-announce if the same message is set twice
    setTimeout(function () {
      statusEl.textContent = 'Preferences saved! You will receive notifications via ' + label + '.';
      statusEl.classList.add('success');
