const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
  const html = fs.readFileSync('index.html', 'utf8');
  const css = fs.readFileSync('styles.css', 'utf8');
  const js = fs.readFileSync('main.js', 'utf8');

  // Inline everything so we don't need a server
  const inlined = html
    .replace('<link rel=\"stylesheet\" href=\"styles.css\" />', '<style>' + css + '</style>')
    .replace('<script src=\"main.js\"></script>', '<script>' + js + '</script>');

  const b = await chromium.launch();
  const page = await b.newPage();
  await page.setContent(inlined, { waitUntil: 'load' });
  await page.addScriptTag({ path: '/tmp/axe.min.js' });
  const r = await page.evaluate(async () => await window.axe.run());
  await b.close();

  const wcag = r.violations.filter(v => !v.tags.includes('best-practice'));
  const bp   = r.violations.filter(v =>  v.tags.includes('best-practice'));
  console.log(JSON.stringify({
    wcag: wcag.map(v => ({ id: v.id, impact: v.impact, desc: v.description, targets: v.nodes.map(n => n.target) })),
    bp:   bp.map(v =>   ({ id: v.id, targets: v.nodes.map(n => n.target) }))
  }, null, 2));
  process.exit(wcag.length ? 1 : 0);
})();
