  await page.addScriptTag({ path: '/tmp/axe.min.js' });
  await page.click('button[type="submit"]');
  await page.waitForTimeout(200); // let live region update
  const r2 = await page.evaluate(async () => await window.axe.run());
  const wcag2 = r2.violations.filter(v => !v.tags.includes('best-practice'));
  console.log('Success state WCAG violations:', JSON.stringify(wcag2.map(v => ({ id: v.id, impact: v.impact }))));

  await b.close();
  process.exit((wcag1.length + wcag2.length) ? 1 : 0);
})();
