*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --color-bg: #f5f6fa;
  --color-surface: #ffffff;
  --color-primary: #4f46e5;
  --color-primary-hover: #4338ca;
  --color-primary-focus-ring: #a5b4fc;
  --color-text: #111827;
  --color-text-muted: #6b7280;
  --color-border: #d1d5db;
  --color-border-hover: #9ca3af;
  --color-error: #b91c1c;
  --color-error-bg: #fef2f2;
  --color-success: #166534;
  --color-success-bg: #f0fdf4;
  --color-radio-checked: #4f46e5;
  --radius-card: 1rem;
  --radius-btn: 0.5rem;
  --shadow-card: 0 4px 24px rgba(0, 0, 0, 0.07);
  --font: 'Inter', system-ui, -apple-system, sans-serif;
}

body {
  font-family: var(--font);
  background: var(--color-bg);
  color: var(--color-text);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  -webkit-font-smoothing: antialiased;
}

/* ── Skip link ───────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  background: var(--color-primary);
  color: #fff;
  padding: 0.5rem 1rem;
  border-radius: var(--radius-btn);
  font-weight: 600;
  text-decoration: none;
  z-index: 100;
  transition: top 0.1s;
}
.skip-link:focus {
  top: 1rem;
}

/* ── Header ──────────────────────────────────────────────────── */
.site-header {
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
  padding: 1rem 0;
}
.logo {
  font-size: 1.125rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--color-primary);
}

/* ── Layout ──────────────────────────────────────────────────── */
.container {
  width: 100%;
  max-width: 600px;
  margin: 0 auto;
  padding: 0 1rem;
}

main.container {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding-top: 3rem;
  padding-bottom: 3rem;
}

/* ── Card ────────────────────────────────────────────────────── */
.card {
  background: var(--color-surface);
  border-radius: var(--radius-card);
  box-shadow: var(--shadow-card);
  padding: 2.5rem;
}

h1 {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 0.5rem;
}

.intro {
  color: var(--color-text-muted);
  font-size: 0.9375rem;
  line-height: 1.6;
  margin-bottom: 2rem;
}

/* ── Form & fieldset ─────────────────────────────────────────── */
.form-field {
  margin-bottom: 2rem;
}

fieldset {
  border: none;
  padding: 0;
  min-width: 0;
}

legend {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--color-text);
  margin-bottom: 0.25rem;
  line-height: 1.5;
}

.required-marker {
  color: var(--color-error);
  margin-left: 0.125rem;
}

.required-note {
  font-size: 0.8125rem;
  color: var(--color-text-muted);
  margin-bottom: 1.25rem;
}

/* ── Radio options ───────────────────────────────────────────── */
.radio-options {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.radio-label {
  display: flex;
  align-items: center;
  gap: 0.875rem;
  padding: 0.875rem 1rem;
  border: 1.5px solid var(--color-border);
  border-radius: 0.625rem;
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s, box-shadow 0.15s;
  position: relative;
}

.radio-label:hover {
  border-color: var(--color-primary);
  background: #f5f3ff;
}

/* Hide native radio visually but keep it accessible */
.radio-label input[type="radio"] {
  position: absolute;
  opacity: 0;
  width: 1.25rem;
  height: 1.25rem;
  margin: 0;
  cursor: pointer;
}

/* Custom radio circle — decorative only; pointer events pass through to the label */
.radio-custom {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 1.25rem;
  height: 1.25rem;
  border: 2px solid var(--color-border-hover);
  border-radius: 50%;
  background: #fff;
  transition: border-color 0.15s, background 0.15s;
  pointer-events: none;
}

.radio-custom::after {
  content: '';
  display: block;
  width: 0.5rem;
  height: 0.5rem;
  border-radius: 50%;
  background: #fff;
  opacity: 0;
  transition: opacity 0.15s;
}

/* Checked state */
.radio-label input[type="radio"]:checked ~ .radio-custom {
  border-color: var(--color-radio-checked);
  background: var(--color-radio-checked);
}

.radio-label input[type="radio"]:checked ~ .radio-custom::after {
  opacity: 1;
}

.radio-label:has(input[type="radio"]:checked) {
  border-color: var(--color-primary);
  background: #ede9fe;
}

/* Focus indicator — visible ring around the card row */
.radio-label input[type="radio"]:focus-visible ~ .radio-custom {
  outline: 2px solid var(--color-primary);
  outline-offset: 2px;
}

.radio-text {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-text);
}

/* ── Error message ───────────────────────────────────────────── */
.error-message {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-top: 0.875rem;
  padding: 0.625rem 0.875rem;
  background: var(--color-error-bg);
  border: 1px solid #fca5a5;
  border-radius: 0.5rem;
  color: var(--color-error);
  font-size: 0.875rem;
  font-weight: 500;
}

.error-message[hidden] {
  display: none;
}

/* Invalid state: highlight option rows */
fieldset.is-invalid .radio-label {
  border-color: #fca5a5;
}

/* ── Submit button ───────────────────────────────────────────── */
.btn-submit {
  width: 100%;
  padding: 0.875rem 1.5rem;
  background: var(--color-primary);
  color: #fff;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius-btn);
  cursor: pointer;
  transition: background 0.15s, box-shadow 0.15s;
  letter-spacing: 0.01em;
}

.btn-submit:hover {
  background: var(--color-primary-hover);
}

.btn-submit:focus-visible {
  outline: 3px solid var(--color-primary-focus-ring);
  outline-offset: 2px;
}

/* ── Status message ──────────────────────────────────────────── */
.status-message {
  margin-top: 1.25rem;
  font-size: 0.9375rem;
  font-weight: 500;
  min-height: 1.5rem;
}

.status-message.success {
  padding: 0.75rem 1rem;
  background: var(--color-success-bg);
  border: 1px solid #86efac;
  border-radius: 0.5rem;
  color: var(--color-success);
}

/* ── Forced colors (Windows High Contrast) ───────────────────── */
@media (forced-colors: active) {
  .radio-custom {
    border: 2px solid ButtonText;
    background: ButtonFace;
    forced-color-adjust: none;
  }
  .radio-label input[type="radio"]:checked ~ .radio-custom {
    background: Highlight;
    border-color: Highlight;
  }
  .radio-label input[type="radio"]:checked ~ .radio-custom::after {
    background: HighlightText;
  }
  .btn-submit {
    border: 2px solid ButtonText;
  }
}

/* ── Reduced motion ──────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition: none !important;
  }
}

/* ── Responsive / reflow (320 px) ────────────────────────────── */
@media (max-width: 480px) {
  .card {
    padding: 1.5rem 1.25rem;
    border-radius: 0.75rem;
  }

  h1 {
    font-size: 1.25rem;
  }
}
