  height: 0.5rem;
  border-radius: 50%;
  background: #fff;
  opacity: 0;
  transition: opacity 0.15s;
}

/* Checked state */
.radio-label input[type="radio"]:checked ~ .radio-custom {
  border-color: var(--color-radio-checked);
  background: var(--color-radio-checked);
}

.radio-label input[type="radio"]:checked ~ .radio-custom::after {
  opacity: 1;
}

.radio-label:has(input[type="radio"]:checked) {
  border-color: var(--color-primary);
  background: #ede9fe;
}

/* Focus indicator — visible ring around the card row */
.radio-label input[type="radio"]:focus-visible ~ .radio-custom {
  outline: 2px solid var(--color-primary);
  outline-offset: 2px;
}

.radio-text {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-text);
}

/* ── Error message ───────────────────────────────────────────── */
.error-message {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-top: 0.875rem;
  padding: 0.625rem 0.875rem;
  background: var(--color-error-bg);
  border: 1px solid #fca5a5;
  border-radius: 0.5rem;
  color: var(--color-error);
  font-size: 0.875rem;
  font-weight: 500;
}

.error-message[hidden] {
  display: none;
}

/* Invalid state: highlight option rows */
fieldset.is-invalid .radio-label {
  border-color: #fca5a5;
}

/* ── Submit button ───────────────────────────────────────────── */
.btn-submit {
  width: 100%;
  padding: 0.875rem 1.5rem;
  background: var(--color-primary);
  color: #fff;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius-btn);
  cursor: pointer;
  transition: background 0.15s, box-shadow 0.15s;
  letter-spacing: 0.01em;
}

.btn-submit:hover {
  background: var(--color-primary-hover);
}

.btn-submit:focus-visible {
  outline: 3px solid var(--color-primary-focus-ring);
  outline-offset: 2px;
}

/* ── Status message ──────────────────────────────────────────── */
.status-message {
  margin-top: 1.25rem;
  font-size: 0.9375rem;
  font-weight: 500;
  min-height: 1.5rem;
}

.status-message.success {
  padding: 0.75rem 1rem;
  background: var(--color-success-bg);
  border: 1px solid #86efac;
  border-radius: 0.5rem;
  color: var(--color-success);
}

/* ── Forced colors (Windows High Contrast) ───────────────────── */
@media (forced-colors: active) {
  .radio-custom {
    border: 2px solid ButtonText;
    background: ButtonFace;
    forced-color-adjust: none;
  }
  .radio-label input[type="radio"]:checked ~ .radio-custom {
    background: Highlight;
    border-color: Highlight;
  }
  .radio-label input[type="radio"]:checked ~ .radio-custom::after {
    background: HighlightText;
  }
  .btn-submit {
    border: 2px solid ButtonText;
  }
}

/* ── Reduced motion ──────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition: none !important;
  }
}

/* ── Responsive / reflow (320 px) ────────────────────────────── */
@media (max-width: 480px) {
  .card {
    padding: 1.5rem 1.25rem;
    border-radius: 0.75rem;
  }

